-- PATCH + REMPLISSAGE COMPATIBLE AVEC TA BASE EXISTANTE
create table if not exists public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid unique,email text unique not null,role text not null default 'user',created_at timestamptz default now());
create table if not exists public.library_history(id uuid primary key default gen_random_uuid(),application text,table_name text,record_id text,action text,field_name text,old_value text,new_value text,user_id uuid,user_email text,created_at timestamptz default now());
alter table public.cnc_materials add column if not exists created_by_user_id uuid, add column if not exists created_by_email text, add column if not exists updated_by_user_id uuid, add column if not exists updated_by_email text, add column if not exists updated_at timestamptz;
alter table public.cnc_tools add column if not exists created_by_user_id uuid, add column if not exists created_by_email text, add column if not exists updated_by_user_id uuid, add column if not exists updated_by_email text, add column if not exists updated_at timestamptz;
alter table public.hot_supports add column if not exists code text, add column if not exists supplier text, add column if not exists collection text, add column if not exists reference text, add column if not exists name_fr text, add column if not exists name_en text, add column if not exists name_pt text, add column if not exists family text, add column if not exists note text, add column if not exists created_by_user_id uuid, add column if not exists created_by_email text, add column if not exists updated_by_user_id uuid, add column if not exists updated_by_email text, add column if not exists updated_at timestamptz;
alter table public.hot_foils add column if not exists created_by_user_id uuid, add column if not exists created_by_email text, add column if not exists updated_by_user_id uuid, add column if not exists updated_by_email text, add column if not exists updated_at timestamptz;
alter table public.laser_materials add column if not exists code text, add column if not exists name_fr text, add column if not exists name_en text, add column if not exists name_pt text, add column if not exists family text, add column if not exists note text, add column if not exists created_by_user_id uuid, add column if not exists created_by_email text, add column if not exists updated_by_user_id uuid, add column if not exists updated_by_email text, add column if not exists updated_at timestamptz;
alter table public.laser_parameters add column if not exists created_by_user_id uuid, add column if not exists created_by_email text, add column if not exists updated_by_user_id uuid, add column if not exists updated_by_email text, add column if not exists updated_at timestamptz;
alter table public.cnc_calibrations add column if not exists created_by_user_id uuid, add column if not exists created_by_email text;
alter table public."Hot_Stamping_calibrations" add column if not exists created_by_user_id uuid, add column if not exists created_by_email text;
alter table public."Laser_calibrations" add column if not exists created_by_user_id uuid, add column if not exists created_by_email text;

alter table public.user_roles enable row level security; alter table public.library_history enable row level security;
-- Policies lecture/ecriture authentifiée
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['user_roles','library_history','cnc_materials','cnc_tools','cnc_machines','cnc_calibrations','hot_supports','hot_foils','hot_machines','Hot_Stamping_calibrations','laser_materials','laser_parameters','laser_machines','Laser_calibrations'] LOOP EXECUTE format('alter table public.%I enable row level security',t); EXECUTE format('drop policy if exists read_all on public.%I',t); EXECUTE format('create policy read_all on public.%I for select to authenticated using (true)',t); EXECUTE format('drop policy if exists write_auth on public.%I',t); EXECUTE format('create policy write_auth on public.%I for all to authenticated using (true) with check (true)',t); END LOOP; END $$;
grant usage on schema public to anon, authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
notify pgrst, 'reload schema';
